import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int M = sc.nextInt();

        int[] forbidden = new int[N];

        for (int i = 0; i < M; i++) {
            int x = sc.nextInt() - 1;
            int y = sc.nextInt() - 1;
            forbidden[x] |= 1 << y;
            forbidden[y] |= 1 << x;
        }

        int total = 1 << N;
        boolean[] valid = new boolean[total];
        valid[0] = true;

        long answer = 0;

        for (int mask = 1; mask < total; mask++) {
            int bit = mask & -mask;
            int v = Integer.numberOfTrailingZeros(bit);
            int prev = mask ^ bit;

            if (valid[prev] && (forbidden[v] & prev) == 0) {
                valid[mask] = true;
                answer++;
            }
        }

        System.out.println(answer);
    }
}
