            int y = Integer.parseInt(st.nextToken()) - 1;

            adj[x] |= 1 << y;
            adj[y] |= 1 << x;
        }

        int limit = 1 << N;
        int answer = 0;

        for (int mask = 1; mask < limit; mask++) {
            boolean ok = true;
            int cur = mask;

            while (cur != 0) {
                int bit = cur & -cur;
                int v = Integer.numberOfTrailingZeros(bit);

                if ((adj[v] & mask) != 0) {
                    ok = false;
                    break;
                }

                cur ^= bit;
            }

            if (ok) {
                answer++;
            }
        }

        System.out.println(answer);
